INSERT INTO `lt_playway` VALUES ('327', '中三特殊号码', '0', '1', '6.00', '6.00', '1', '3', '选择一个号码形态。', '所选的号码特殊属性和开奖号码中3位的属性一致，即为中奖。其中：1.顺子号的十、百、千位不分顺序；2.对子号指的是开奖号码的中三位当中，任意2位数字相同的三位数号码。', '', 'sxzxz3ts', 'sscz3tshm', '', 'ssc_ts_z3', '0', '9', '0', '3', '3');
INSERT INTO `lt_playway` VALUES ('328', '前三特殊号码', '0', '1', '6.00', '6.00', '1', '2', '选择一个号码形态。', '所选的号码特殊属性和开奖号码前3位的属性一致，即为中奖。其中：1.顺子号的百、千、万位不分顺序；2.对子号指的是开奖号码的前三位当中，任意2位数字相同的三位数号码。', '', 'sxzxq3ts', 'sscq3tshm', '', 'ssc_ts_q3', '0', '9', '0', '3', '3');
